size_t
UA_calcSizeJson(const void *src, const UA_DataType *type, ...) {
    CtxJson ctx;
    memset(&ctx, 0, sizeof(ctx));
    ctx.pos = 0;
    ctx.end = (const UA_Byte*)(uintptr_t)SIZE_MAX;
    ...
    ctx.calcOnly = true;
